# Apply the transformation: each component shifts so its top row becomes row 1
test_input = [[0]*30 for _ in range(17)]

def make_solid_cross(r_start, c_start, color):
    for i in range(-1, 2):
        for j in range(-1, 2):
            r, c = r_start + i, c_start + j
            if 0 <= r < 17 and 0 <= c < 30:
                test_input[r][c] = color

make_solid_cross(3, 16, color=4)   # rows 2-4
make_solid_cross(8, 27, color=8)   # rows 7-9
make_solid_cross(11, 3, color=3)   # rows 10-12
make_solid_cross(14, 11, color=1)  # rows 13-15

# Find components
visited = set()
height = len(test_input)
width = len(test_input[0])

components = []
for r in range(height):
    for c in range(width):
        color = test_input[r][c]
        if color != 0 and (r, c) not in visited:
            comp_cells = []
            queue = [(r,c)]
            visited.add((r,c))

            while queue:
                cr, cc = queue.pop(0)
                comp_cells.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if (nr, nc) not in visited and 0 <= nr < height and 0 <= nc < width:
                        if test_input[nr][nc] == color:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            min_r = min(cell[0] for cell in comp_cells)
            max_r = max(cell[0] for cell in comp_cells)
            min_c = min(cell[1] for cell in comp_cells)
            max_c = max(cell[1] for cell in comp_cells)

            shift = 1 - min_r  # Move top to row 1

            components.append({
                'color': color,
                'cells': [(cell[0] + shift, cell[1]) for cell in comp_cells],
                'shift': shift
            })

            print(f"Color {color}: original rows [{min_r},{max_r}], shift={shift}, new rows [{1},{max_r+shift}]")

# Build output grid
output_grid = [[0]*width for _ in range(17)]
for comp in components:
    for r, c in comp['cells']:
        if 0 <= r < 17 and 0 <= c < width:
            output_grid[r][c] = comp['color']

print("\n=== OUTPUT GRID ===")
for r_idx, row in enumerate(output_grid):
    print(f"{r_idx}: {' '.join(str(x) for x in row)}")

# Verify: check what we got
print("\n=== Verification ===")
colors_seen = {}
for r in range(17):
    for c in range(30):
        color = output_grid[r][c]
        if color != 0:
            if color not in colors_seen:
                colors_seen[color] = []
            colors_seen[color].append((r,c))

for color, cells in sorted(colors_seen.items()):
    min_r = min(c[0] for c in cells)
    print(f"Color {color}: starts at row {min_r} (should be 1)")

